// Primitive Initialization
int count{};    // Zero initialization (0)
int value{42};  // Uniform initialization (preferred)
double pi = 3.1415; // Copy initialization

// Aggregate Initialization
struct Vector { float x, y; };
Vector v{1.0f, 2.0f};

// Class Member Initialization
class State {
    // In-class default initializers (C++11)
    int id_{0};
    bool connected_{false};

public:
    // Member Initializer List (Best practice for constructors)
    State(int i) : id_(i) {}
};
